import { useEffect, useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Atom, BookOpen, BrainCircuit, Calculator, Check, ChevronRight, Code2, Compass, FlaskConical, Gamepad2, GraduationCap, Globe2, Lightbulb, Menu, Moon, Rocket, Search, Settings2, ShieldCheck, Sparkles, Sun, Trophy, Volume2, Zap } from 'lucide-react';

type Game = { id: string; title: string; category: string; description: string; emoji: string; color: string; };
const games: Game[] = [
 { id:'turbo-car-racer',title:'Meteor Dash',category:'Arcade racer',description:'Pick a lane, dodge space rocks, and scoop up stardust on a bright cosmic course.',emoji:'🏎️',color:'coral' },
 { id:'veggie-slice',title:'Rainbow Garden',category:'Garden quest',description:'Build a colorful snack, meet garden friends, and discover what plants need to grow.',emoji:'🥕',color:'lime' },
 { id:'mine-blast',title:'Crystal Memory',category:'Memory puzzle',description:'Flip glowing crystals, remember their places, and find every matching pair.',emoji:'💎',color:'violet' },
 { id:'river-boat-adventure',title:'River Rescue',category:'Choose-your-path',description:'Guide a rescue boat through changing currents, make thoughtful choices, and deliver supplies.',emoji:'🛶',color:'blue' },
 { id:'space-explorer',title:'Planet Pathfinder',category:'Space mission',description:'Choose a world, pick a science instrument, and collect discoveries across the Solar System.',emoji:'🚀',color:'gold' },
];
const subjects = [
 {name:'Mathematics',sub:'Patterns, numbers & logic',icon:Calculator,color:'violet',fact:'A googol is the number 1 followed by 100 zeros.',lesson:'Try a number pattern: 2, 4, 8, 16… Each number doubles. What comes next?',task:'Solve: 12 × 8 = ?',answer:'96'},
 {name:'Chemistry',sub:'Atoms, elements & reactions',icon:FlaskConical,color:'lime',fact:'Water is made from two hydrogen atoms and one oxygen atom: H₂O.',lesson:'Atoms are tiny building blocks. Elements contain one kind of atom; compounds join different elements.',task:'What is the chemical formula for water?',answer:'H2O'},
 {name:'Physics',sub:'Motion, energy & forces',icon:Atom,color:'blue',fact:'Light travels about 300,000 kilometres every second in a vacuum.',lesson:'A force is a push or pull. Friction is a force that resists sliding between surfaces.',task:'Which force pulls objects toward Earth?',answer:'gravity'},
 {name:'AI',sub:'Smart machines & responsible AI',icon:BrainCircuit,color:'coral',fact:'Machine learning finds patterns in examples to make useful predictions.',lesson:'AI can help classify pictures, translate languages, and answer questions. People should check important answers.',task:'AI learns patterns from what?',answer:'data'},
 {name:'Computer Science',sub:'Coding, algorithms & systems',icon:Code2,color:'violet',fact:'An algorithm is a set of steps for solving a problem.',lesson:'A loop repeats instructions. A condition lets a program choose what to do.',task:'What coding structure repeats steps?',answer:'loop'},
 {name:'Latest Inventions',sub:'Ideas changing our world',icon:Lightbulb,color:'gold',fact:'Engineers use prototypes to test ideas before building a final product.',lesson:'Inventions often improve through testing, feedback, and redesign. Good ideas solve real problems.',task:'What is an early test version of a product called?',answer:'prototype'},
 {name:'Universe & Space',sub:'Planets, stars & galaxies',icon:Rocket,color:'blue',fact:'A day on Venus is longer than its year.',lesson:'Our solar system has eight planets orbiting the Sun. The Sun is a star at the centre.',task:'Which star is closest to Earth?',answer:'sun'},
 {name:'General Knowledge',sub:'Nature, history & our world',icon:Globe2,color:'lime',fact:'Earth has one natural satellite: the Moon.',lesson:'Curiosity grows when you ask questions, compare reliable sources, and explain what you discover.',task:'What is Earth’s natural satellite?',answer:'moon'},
];
const codingLessons = [
 {title:'Make a square move',level:'Starter',time:'5 min',code:'let x = 20;\nfunction moveRight() {\n  x = x + 10;\n  return x;\n}',task:'Change +10 to +20. How much farther does the square move each tap?'},
 {title:'Collect the star',level:'Starter',time:'8 min',code:'let score = 0;\nfunction collectStar() {\n  score = score + 1;\n  return score;\n}',task:'Add 5 points instead of 1. What score do you get after 3 stars?'},
 {title:'Build a Snake game',level:'Explorer',time:'12 min',code:'const snake = [{ x: 3, y: 3 }];\nfunction move(dx, dy) {\n  const head = snake[0];\n  snake.unshift({ x: head.x + dx, y: head.y + dy });\n}',task:'Try move(1, 0) to move right. What values would move the snake up?'},
 {title:'Design a tiny car game',level:'Explorer',time:'10 min',code:'let distance = 0;\nfunction accelerate() {\n  distance += 2;\n  return distance;\n}',task:'Change the acceleration from 2 to 3 and compare 5 presses.'},
 {title:'Launch a rocket',level:'Builder',time:'10 min',code:'let fuel = 10;\nfunction launch() {\n  if (fuel > 0) fuel -= 1;\n  return fuel;\n}',task:'Why do we check fuel > 0 before subtracting?'},
];
const lessons = [
 {title:'The power of patterns',subject:'Mathematics',duration:'6 min',emoji:'🔢',text:'A pattern is a sequence that follows a rule. To predict its next part, compare neighboring terms and ask what operation repeats.',example:'In 3, 6, 12, 24, each term is multiplied by 2. So the next term is 48. Check the rule against every pair, not just the first one.',pitfall:'A sequence can fit more than one rule when it is short. Choose the simplest rule that explains all the terms you can see.',question:'What comes next: 5, 10, 20, 40, …?',answer:'80',reflect:'Where have you noticed a repeating pattern outside math?'},
 {title:'Meet the atom',subject:'Chemistry',duration:'7 min',emoji:'⚛️',text:'All ordinary matter is made of atoms. Each atom has a tiny nucleus with protons and neutrons, surrounded by electrons. The number of protons identifies the element.',example:'A helium atom has 2 protons, so it is helium. A neutral helium atom also has 2 electrons; it usually has 2 neutrons, too.',pitfall:'Atoms are not tiny solar systems: electrons do not travel along neat planet-like tracks. The model is a helpful picture, not a literal map.',question:'Which particle count decides what element an atom is?',answer:'protons',reflect:'Name something near you that is made of atoms.'},
 {title:'Why things move',subject:'Physics',duration:'8 min',emoji:'🛹',text:'A force is a push or pull. Forces can start, stop, speed up, slow down, or change the direction of motion. If forces balance, motion does not change.',example:'Push a toy car across a floor: your push moves it forward, while friction between its wheels and the floor resists the motion. A stronger push can make it speed up.',pitfall:'Objects do not need a continuous push to keep moving. With very little friction, a moving object keeps moving; friction is what gradually slows everyday objects.',question:'What force between surfaces often slows a sliding object?',answer:'friction',reflect:'What could you change to help a toy car roll farther?'},
 {title:'How AI learns',subject:'AI',duration:'5 min',emoji:'🧠',text:'A machine-learning model finds patterns in examples. During training it adjusts its internal settings; later it uses the patterns to make a prediction on new input.',example:'Show a model many labeled photos of cats and dogs. It may learn visual clues and classify a new photo, but its answer is a prediction, not a guarantee.',pitfall:'More examples do not automatically mean better results. If the examples are incomplete or unfairly skewed, predictions can repeat those gaps.',question:'What does a machine-learning model use to find patterns?',answer:'examples',reflect:'When should a person double-check an AI answer?'},
 {title:'Think like a programmer',subject:'Computer Science',duration:'8 min',emoji:'💻',text:'An algorithm is a precise set of steps for a task. Programmers split a problem into smaller pieces, write instructions, test them, and revise when results differ from expectations.',example:'To make toast: get bread, place it in the toaster, start the toaster, wait, then remove it carefully. The order matters, and a missing step can break the process.',pitfall:'Computers follow instructions literally. “Do it until it looks right” is vague; a useful algorithm needs steps or conditions that can be checked.',question:'What is a precise set of steps for solving a problem called?',answer:'algorithm',reflect:'Describe one everyday routine as three clear steps.'},
 {title:'Explore the Solar System',subject:'Universe & Space',duration:'9 min',emoji:'🪐',text:'The Solar System includes the Sun, eight planets, their moons, and many smaller bodies. The Sun’s gravity bends their paths into orbits; a planet is continually moving as it orbits.',example:'Earth takes about 365 days to orbit the Sun. Its tilted axis, together with that orbit, gives us the seasons; distance from the Sun is not the main cause.',pitfall:'Seasons are not caused by Earth being much closer to or farther from the Sun. Earth’s tilt changes the angle and length of sunlight in each hemisphere.',question:'What is the main cause of Earth’s seasons?',answer:'tilt',reflect:'How might daylight change if a planet had no axial tilt?'},
];
const lessonsBySubject = (s:string) => lessons.filter(l=>l.subject===s);
const challengeHints: Record<string,string> = {
 Mathematics:'Multiply 12 by 8, or split it into 10 × 8 and 2 × 8.',
 Chemistry:'Look at the symbols for hydrogen and oxygen, and count the atoms in one water molecule.',
 Physics:'Think of the force you feel when sliding your hand across a rough surface.',
 AI:'Training examples are collected together so the system can look for patterns.',
 'Computer Science':'A loop is one example; it runs the same instructions again.',
 'Latest Inventions':'It is a first version built to test an idea before making the final product.',
 'Universe & Space':'It is the star our planet orbits.',
 'General Knowledge':'It is the object that orbits Earth at night.',
};
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const supabaseKey = (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || import.meta.env.VITE_SUPABASE_ANON_KEY) as string | undefined;
const supabase: SupabaseClient | null = supabaseUrl && supabaseKey ? createClient(supabaseUrl,supabaseKey) : null;

export default function App() {
 const [dark,setDark] = useState(()=>localStorage.getItem('kq-theme') !== 'light');
 const [active,setActive] = useState('Home');
 const [selectedSubject,setSelectedSubject] = useState('Mathematics');
 const [search,setSearch] = useState('');
 const [mobileNav,setMobileNav] = useState(false);
 const [activeGame,setActiveGame] = useState<Game | null>(null);
 const [notice,setNotice] = useState('');
 const [name,setName] = useState(()=>localStorage.getItem('kq-name') || 'Young Explorer');
 const [draftName,setDraftName] = useState(name);
 const [completed,setCompleted] = useState<string[]>(()=>JSON.parse(localStorage.getItem('kq-completed')||'[]'));
 const [points,setPoints] = useState(()=>Number(localStorage.getItem('kq-points')||0));
 const [answer,setAnswer] = useState('');
 const [taskFeedback,setTaskFeedback] = useState('');
 const [chosenLesson,setChosenLesson] = useState<typeof lessons[number] | null>(null);
 const [lessonAnswer,setLessonAnswer] = useState('');
 const [lessonFeedback,setLessonFeedback] = useState('');
 const [lessonMastered,setLessonMastered] = useState(false);
 const [showLessonHint,setShowLessonHint] = useState(false);
 const [sandboxOutput,setSandboxOutput] = useState('Your code output will appear here.');
 const [authUser,setAuthUser] = useState<{id:string;email?:string}|null>(null);
 const [authEmail,setAuthEmail] = useState('');
 const [authPassword,setAuthPassword] = useState('');
 const [authMode,setAuthMode] = useState<'signin'|'signup'>('signin');
 const [authBusy,setAuthBusy] = useState(false);
 useEffect(()=>{localStorage.setItem('kq-theme',dark?'dark':'light');document.documentElement.dataset.theme=dark?'dark':'light';},[dark]);
 useEffect(()=>{localStorage.setItem('kq-points',String(points));},[points]);
 useEffect(()=>{localStorage.setItem('kq-completed',JSON.stringify(completed));},[completed]);
 useEffect(()=>{localStorage.setItem('kq-name',name);},[name]);
 useEffect(()=>{
  if(!supabase) return;
  let alive=true;
  supabase.auth.getSession().then(({data})=>{if(alive){const u=data.session?.user;setAuthUser(u?{id:u.id,email:u.email}:null);}});
  const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>{const u=session?.user;setAuthUser(u?{id:u.id,email:u.email}:null);});
  return ()=>{alive=false;subscription.unsubscribe();};
 },[]);
 useEffect(()=>{
  if(!supabase||!authUser) return;
  supabase.from('profiles').upsert({id:authUser.id,display_name:name},{onConflict:'id'}).then(({error})=>{
   if(error) setNotice('Signed in, but profile sync needs attention. Check that supabase/schema.sql has been applied.');
  });
 },[authUser?.id]);
 const filteredSubjects=useMemo(()=>subjects.filter(s=>(s.name+' '+s.sub).toLowerCase().includes(search.toLowerCase())),[search]);
 const navGroups=[{title:'LEARN',items:[{name:'Home',icon:Compass},{name:'My Learning',icon:BookOpen},{name:'Subjects',icon:GraduationCap}]},{title:'PLAY & CREATE',items:[{name:'Fun Games',icon:Gamepad2},{name:'Game Development',icon:Code2},{name:'Quizzes',icon:Zap}]},{title:'YOUR SPACE',items:[{name:'Leaderboard',icon:Trophy},{name:'My Progress',icon:Sparkles},{name:'Settings',icon:Settings2}]}];
 const go=(page:string)=>{setActive(page);setActiveGame(null);setMobileNav(false);setNotice('');};
 const complete=(id:string,award=10)=>{if(!completed.includes(id)){setCompleted(old=>[...old,id]);setPoints(p=>p+award);} };
 const openGame=(g:Game)=>{setActiveGame(g);setActive('Fun Games');setNotice('');};
 const handleAuth=async(e:FormEvent<HTMLFormElement>)=>{
  e.preventDefault();
  if(!supabase){setNotice('Add the Knowledge Quest Supabase URL and publishable key to enable login.');return;}
  setAuthBusy(true);setNotice('');
  try{
   if(authMode==='signup'){
    const {data,error}=await supabase.auth.signUp({email:authEmail.trim(),password:authPassword,options:{data:{display_name:name}}});
    if(error) throw error;
    if(data.session){setNotice('Account created and signed in. Welcome to Knowledge Quest!');}
    else{setNotice('Account created. Check your email to confirm your address, then sign in.');setAuthMode('signin');}
   }else{
    const {error}=await supabase.auth.signInWithPassword({email:authEmail.trim(),password:authPassword});
    if(error) throw error;
    setNotice('You are signed in. Your cloud profile is ready.');
   }
   setAuthPassword('');
  }catch(error){setNotice(error instanceof Error?error.message:'Unable to complete sign-in. Please try again.');}
  finally{setAuthBusy(false);}
 };
 const handleSignOut=async()=>{
  if(!supabase)return;
  const {error}=await supabase.auth.signOut();
  setNotice(error?error.message:'Signed out. This device keeps its local demo progress.');
 };
 const finishGame=async(final:number)=>{setPoints(p=>p+final);setNotice(`Mission complete! You earned ${final} stars.`);if(supabase){const {data}=await supabase.auth.getUser();if(data.user && activeGame){await supabase.from('game_sessions').insert({user_id:data.user.id,game_id:activeGame.id,score:final,duration_seconds:0});await supabase.from('student_scores').upsert({user_id:data.user.id,activity_type:'game',activity_id:activeGame.id,points:final,best_score:final},{onConflict:'user_id,activity_type,activity_id'});}}};
 const submitAnswer=(s:typeof subjects[number])=>{if(answer.trim().toLowerCase().replace(/\s/g,'')===s.answer.toLowerCase().replace(/\s/g,'')){setTaskFeedback('Brilliant! That’s correct. '+challengeHints[s.name]+' +10 stars ✨');complete('quiz-'+s.name,10);}else setTaskFeedback('Good try! Hint: '+challengeHints[s.name]);};
 const runSnippet=(lesson:typeof codingLessons[number])=>{const nums=lesson.code.match(/\+\s*(\d+)/g);const increment=nums?.[0]?.match(/\d+/)?.[0];setSandboxOutput(lesson.title+': example ready.\nTry the task below, then edit the code in your local editor to experiment safely.'+(increment?'\nDetected increment: '+increment:''));};
 const heading=activeGame?.title || active;
 const currentSubject=subjects.find(s=>s.name===selectedSubject)||subjects[0];
 return <div className="app-shell">
  <aside className={'sidebar '+(mobileNav?'sidebar-open':'')}>
   <div className="brand"><div className="brand-mark"><Sparkles size={22}/></div><div><strong>knowledge<span>quest</span></strong><small>PLAY. DISCOVER. LEARN.</small></div><button className="icon-button close-nav" onClick={()=>setMobileNav(false)} aria-label="Close navigation">×</button></div>
   <div className="profile-mini"><div className="avatar">🧑‍🚀</div><div className="profile-copy"><strong>{name}</strong><span>Level {Math.floor(points/100)+1} Explorer</span></div><span className="online-dot"/></div>
   {navGroups.map(group=><div className="nav-group" key={group.title}><div className="nav-label">{group.title}</div>{group.items.map(item=><button key={item.name} className={'nav-item '+(active===item.name?'nav-active':'')} onClick={()=>go(item.name)}><item.icon size={18}/><span>{item.name}</span>{item.name==='Fun Games'&&<span className="nav-count">5</span>}</button>)}</div>)}
   <div className="sidebar-bottom"><div className="streak-card"><div className="streak-icon">🔥</div><div><strong>Keep your streak!</strong><p>A little learning every day adds up.</p></div></div><button className="theme-toggle" onClick={()=>setDark(!dark)}>{dark?<Sun size={17}/>:<Moon size={17}/>}<span>{dark?'Switch to light mode':'Switch to dark mode'}</span><span className="toggle-track"><i/></span></button><div className="sidebar-footer">Made for curious minds <span>✦</span></div></div>
  </aside>
  {mobileNav&&<button className="mobile-scrim" onClick={()=>setMobileNav(false)} aria-label="Close menu"/>}
  <main className="main-area">
   <header className="topbar"><button className="icon-button menu-button" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Menu size={20}/></button><div className="breadcrumbs">Workspace <ChevronRight size={14}/><span>{heading}</span></div><div className="top-actions"><label className="search-box"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search anything..." aria-label="Search subjects"/></label><button className="icon-button theme-top" onClick={()=>setDark(!dark)} aria-label="Toggle theme">{dark?<Sun size={18}/>:<Moon size={18}/>}</button><div className="top-avatar">🧑‍🚀</div></div></header>
   <div className="page-content">
   {active==='Home'&&!activeGame&&<><section className="hero-panel"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot"/> YOUR NEXT BIG DISCOVERY STARTS HERE</div><h1>Curiosity is your<br/><span>superpower.</span></h1><p>Explore big ideas, solve little challenges, and turn what you learn into something amazing.</p><div className="hero-buttons"><button className="btn-primary" onClick={()=>go('Subjects')}>Start exploring <ChevronRight size={17}/></button><button className="btn-quiet" onClick={()=>go('Fun Games')}><Gamepad2 size={17}/> Play a game</button></div><div className="hero-social"><div className="tiny-avatars"><span>🧑🏻‍🔬</span><span>👩🏽‍🚀</span><span>🧒🏼</span></div><span>Little steps. Big discoveries.</span></div></div><div className="hero-art"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="planet planet-purple">✦</div><div className="planet planet-blue"/><div className="planet planet-orange"/><div className="floating-card card-top"><span>✨</span><div><strong>Wonder unlocked!</strong><small>Every question counts</small></div></div><div className="astronaut">🧑‍🚀</div><div className="floating-card card-bottom"><span>🚀</span><div><strong>Ready for launch</strong><small>Your next mission awaits</small></div></div><span className="star star-a">✦</span><span className="star star-b">✧</span><span className="star star-c">✦</span></div></section>
    <section className="stats-grid"><Stat icon={<Zap size={18}/>}label="TOTAL STARS" value={points.toLocaleString()} note="Every star is progress" color="gold"/><Stat icon={<BookOpen size={18}/>}label="LESSONS DONE" value={String(completed.length)} note="Keep the momentum" color="blue"/><Stat icon={<Trophy size={18}/>}label="EXPLORER LEVEL" value={String(Math.floor(points/100)+1)} note={100-points%100+' stars to level up'} color="violet"/><Stat icon={<ShieldCheck size={18}/>}label="SKILLS UNLOCKED" value={String(Math.min(8,Math.floor(completed.length/2)))} note="Your toolkit is growing" color="lime"/></section>
    <section className="section-block"><div className="section-heading"><div><div className="section-kicker">PICK YOUR PATH</div><h2>Explore a universe of ideas</h2><p>Choose a subject. Follow your curiosity wherever it leads.</p></div><button className="text-link" onClick={()=>go('Subjects')}>All subjects <ChevronRight size={15}/></button></div><div className="subject-grid">{subjects.slice(0,4).map(s=><SubjectCard key={s.name} subject={s} onClick={()=>{setSelectedSubject(s.name);go('Subjects')}}/>)}</div></section>
    <section className="section-block games-preview"><div className="section-heading"><div><div className="section-kicker">TAKE A PLAY BREAK</div><h2>Learning, with a little extra fun</h2><p>Five mini adventures. New skills in every round.</p></div><button className="text-link" onClick={()=>go('Fun Games')}>View all games <ChevronRight size={15}/></button></div><div className="game-grid">{games.slice(0,3).map(g=><GameCard key={g.id} game={g} onClick={()=>openGame(g)}/>)}</div></section>
   </>}
   {active==='Subjects'&&!activeGame&&<><PageIntro kicker="YOUR LEARNING UNIVERSE" title="Explore every subject." text="Short lessons, surprising facts, and little challenges to stretch your mind."/><div className="subject-layout"><div className="subject-list">{filteredSubjects.map(s=><button key={s.name} className={'subject-row '+(selectedSubject===s.name?'subject-row-active':'')} onClick={()=>{setSelectedSubject(s.name);setAnswer('');setTaskFeedback('')}}><span className={'subject-icon '+s.color}><s.icon size={19}/></span><span><strong>{s.name}</strong><small>{s.sub}</small></span><ChevronRight size={17}/></button>)}</div><div className="subject-detail"><div className={'detail-illustration '+currentSubject.color}><div className="detail-orbit"/><currentSubject.icon size={66}/><span>✦</span><i>✧</i></div><div className="detail-meta"><span className="pill">QUICK LESSON</span><span>~ 5 minutes</span></div><h2>{currentSubject.name}</h2><p>{currentSubject.lesson}</p><div className="fact-box"><Sparkles size={18}/><div><strong>Did you know?</strong><p>{currentSubject.fact}</p></div></div><div className="challenge-box"><div className="challenge-top"><span>✦ MINI CHALLENGE</span><span>+10 stars</span></div><h3>{currentSubject.task}</h3><form onSubmit={e=>{e.preventDefault();submitAnswer(currentSubject)}}><input value={answer} onChange={e=>setAnswer(e.target.value)} placeholder="Type your answer..." aria-label="Challenge answer"/><button className="btn-primary" type="submit">Check answer <ChevronRight size={15}/></button></form>{taskFeedback&&<p className="feedback">{taskFeedback}</p>}</div></div></div><section className="section-block"><div className="section-heading"><div><div className="section-kicker">KEEP DISCOVERING</div><h2>Recommended lessons</h2><p>Learn an idea, study an example, then check what stuck.</p></div></div><div className="lesson-grid">{lessons.map(l=><button className="lesson-card" key={l.title} onClick={()=>{setChosenLesson(l);setLessonAnswer('');setLessonFeedback('');setLessonMastered(completed.includes(l.title));setShowLessonHint(false)}}><span className="lesson-emoji">{l.emoji}</span><span className="lesson-subject">{l.subject}</span><strong>{l.title}</strong><small>{completed.includes(l.title)?'Review lesson':'Teach · example · check'} <ChevronRight size={14}/></small></button>)}</div></section></>}
   {active==='Fun Games'&&!activeGame&&<><PageIntro kicker="ARCADE MODE: ACTIVATED" title="Play your next adventure." text="Five hands-on missions with real choices, satisfying progress, and a little discovery in every round."/><div className="game-banner"><div><span className="section-kicker">READY PLAYER ONE?</span><h2>Five games. Five ways to grow.</h2><p>Race the stars, solve a memory puzzle, grow a garden, guide a rescue, or plan a science mission.</p></div><div className="banner-rocket">🚀</div></div><div className="game-grid game-grid-all">{games.map(g=><GameCard key={g.id} game={g} onClick={()=>openGame(g)}/>)}</div><div className="info-note"><ShieldCheck size={18}/><span>Every game is a friendly practice space: try an idea, see what happens, and keep going.</span></div></>}
    {active==='Fun Games'&&activeGame&&<><button className="back-link" onClick={()=>setActiveGame(null)}>← Back to all games</button><GameExperience key={activeGame.id} game={activeGame} onFinish={finishGame}/>{notice&&<div className="success-note game-award" role="status">{notice}</div>}</>}
   {active==='Game Development'&&!activeGame&&<><PageIntro kicker="FROM PLAYER TO CREATOR" title="Learn to build games." text="Small coding experiments help you understand how games work. Pick a mission, read the code, then try the task."/><div className="code-banner"><div className="code-symbol"><Code2 size={36}/></div><div><span className="section-kicker">YOUR FIRST GAME STUDIO</span><h2>Think it. Code it. Play it.</h2><p>Beginner-friendly examples in JavaScript. No setup required to read along.</p></div></div><div className="coding-grid">{codingLessons.map((l,i)=><article className="coding-card" key={l.title}><div className="coding-head"><span className="coding-index">0{i+1}</span><span className="pill">{l.level}</span><span className="coding-time">{l.time}</span></div><h3>{l.title}</h3><pre><code>{l.code}</code></pre><div className="task-label">YOUR SMALL TASK</div><p>{l.task}</p><button className="btn-secondary" onClick={()=>runSnippet(l)}>Explore this example <ChevronRight size={15}/></button></article>)}</div><div className="sandbox-preview"><div className="sandbox-head"><div><span className="section-kicker">EXPERIMENT ZONE</span><h2>Safe code sandbox preview</h2></div><span className="pill">DEMO MODE</span></div><p>This preview explains each example without executing arbitrary code. Use a local editor to change the snippet, run it, and compare the output.</p><pre className="output-box">{sandboxOutput}</pre><div className="info-note"><ShieldCheck size={18}/><span>For safety, this learning dashboard doesn't run untrusted JavaScript entered by visitors.</span></div></div></>}
   {active==='My Learning'&&!activeGame&&<><PageIntro kicker="YOUR LEARNING JOURNEY" title="Every little step counts." text="Pick up where you left off, and celebrate the things you have figured out."/><div className="progress-hero"><div><span className="section-kicker">YOUR EXPLORER SCORE</span><h2>{points} <small>stars</small></h2><p>{completed.length} challenges completed. Keep collecting knowledge!</p></div><div className="progress-ring"><Trophy size={34}/><strong>LV {Math.floor(points/100)+1}</strong></div></div><div className="section-heading"><div><h2>Learning paths</h2><p>Mark a lesson complete to grow your score.</p></div></div><div className="learning-list">{lessons.map(l=><div className="learning-row" key={l.title}><span className="lesson-emoji">{l.emoji}</span><div><strong>{l.title}</strong><small>{l.subject} · {l.duration}</small></div>{completed.includes(l.title)?<button className="btn-secondary" onClick={()=>{setChosenLesson(l);setLessonAnswer('');setLessonFeedback('');setLessonMastered(true);setShowLessonHint(false)}}>Review lesson <ChevronRight size={14}/></button>:<button className="btn-secondary" onClick={()=>{setChosenLesson(l);setLessonAnswer('');setLessonFeedback('');setLessonMastered(false);setShowLessonHint(false)}}>Start lesson <ChevronRight size={14}/></button>}</div>)}</div></>}
   {active==='Quizzes'&&!activeGame&&<><PageIntro kicker="QUICK THINKING" title="Ready for a brain boost?" text="Choose a topic, answer a tiny question, and earn stars for each correct answer."/><div className="quiz-grid">{subjects.map(s=><button className="quiz-card" key={s.name} onClick={()=>{setSelectedSubject(s.name);go('Subjects')}}><span className={'subject-icon '+s.color}><s.icon size={20}/></span><strong>{s.name} quiz</strong><p>{s.task}</p><span className="text-link">Take challenge <ChevronRight size={14}/></span></button>)}</div></>}
   {active==='Leaderboard'&&!activeGame&&<><PageIntro kicker="CELEBRATE PROGRESS" title="The star seekers." text="Your personal score is saved on this device. Connect Supabase to enable shared student profiles and a global leaderboard."/><div className="leaderboard-card"><div className="leader-head"><Trophy size={22}/><div><h2>Explorer leaderboard</h2><p>Local demo view · your device only</p></div></div><div className="leader-row"><span className="rank">1</span><span className="leader-avatar">🧑‍🚀</span><strong>{name}</strong><span className="leader-points">{points} ⭐</span></div><div className="info-note"><ShieldCheck size={18}/><span>To show other students' scores, configure Supabase Auth and run the included schema. Never expose a Supabase service-role key in the browser.</span></div></div></>}
   {active==='My Progress'&&!activeGame&&<><PageIntro kicker="LOOK HOW FAR YOU'VE COME" title="Your progress, at a glance." text="Learning is not a race. Notice what you have practiced and pick your next small goal."/><div className="stats-grid progress-stats"><Stat icon={<Zap size={18}/>}label="STARS EARNED" value={String(points)} note="One step at a time" color="gold"/><Stat icon={<Check size={18}/>}label="COMPLETED" value={String(completed.length)} note="Lessons and challenges" color="lime"/><Stat icon={<Trophy size={18}/>}label="CURRENT LEVEL" value={String(Math.floor(points/100)+1)} note="Earn stars to level up" color="violet"/></div><div className="progress-track-wrap"><div className="progress-label"><strong>Next level</strong><span>{points%100}/100 stars</span></div><div className="progress-track"><i style={{width:(points%100)+'%'}}/></div></div><h2 className="subsection-title">Recently completed</h2>{completed.length?<div className="learning-list">{completed.map(c=><div className="learning-row" key={c}><span className="completed-check"><Check size={16}/></span><div><strong>{c}</strong><small>Added to your learning journey</small></div><span className="completed-label">Done</span></div>)}</div>:<div className="empty-state">Your first star is waiting. Complete a lesson or challenge to get started! ✨</div>}</>}
   {active==='Settings'&&!activeGame&&<><PageIntro kicker="MAKE IT YOUR SPACE" title="Settings & preferences." text="Set your explorer name and personalize your learning experience."/><div className="settings-card"><h2>Explorer profile</h2><label className="field-label">Display name</label><input className="settings-input" value={draftName} onChange={e=>setDraftName(e.target.value)} maxLength={40}/><button className="btn-primary" onClick={()=>{setName(draftName.trim()||'Young Explorer');setNotice('Profile updated on this device.')}}>Save profile <Check size={16}/></button>{notice&&<p className="feedback">{notice}</p>}<div className="settings-divider"/><h3>Appearance</h3><p>Choose the look that feels right for you.</p><div className="theme-options"><button className={!dark?'theme-option selected':'theme-option'} onClick={()=>setDark(false)}><Sun size={20}/> Light mode {!dark&&<Check size={15}/>}</button><button className={dark?'theme-option selected':'theme-option'} onClick={()=>setDark(true)}><Moon size={20}/> Dark mode {dark&&<Check size={15}/>}</button></div><div className="settings-divider"/><h3>Supabase account</h3><p>{!supabase?'Login is not configured yet. Add your separate Knowledge Quest Supabase project URL and publishable key in the app environment settings.':authUser?'Signed in as '+(authUser.email||'your account')+'. Cloud profile sync is enabled.':'Create a student account or sign in to sync your profile.'}</p>{supabase&&!authUser&&<><div className="theme-options"><button type="button" className={authMode==='signin'?'theme-option selected':'theme-option'} onClick={()=>setAuthMode('signin')}>Sign in</button><button type="button" className={authMode==='signup'?'theme-option selected':'theme-option'} onClick={()=>setAuthMode('signup')}>Create account</button></div><form onSubmit={handleAuth}><label className="field-label">Email address</label><input className="settings-input" type="email" autoComplete="email" required value={authEmail} onChange={e=>setAuthEmail(e.target.value)} placeholder="student@example.com"/><label className="field-label">Password (minimum 6 characters)</label><input className="settings-input" type="password" autoComplete={authMode==='signup'?'new-password':'current-password'} minLength={6} required value={authPassword} onChange={e=>setAuthPassword(e.target.value)} placeholder="Enter password"/><button className="btn-primary" type="submit" disabled={authBusy}>{authBusy?'Please wait…':authMode==='signup'?'Create student account':'Sign in'} <ChevronRight size={15}/></button></form></>}{supabase&&authUser&&<button className="btn-secondary" onClick={handleSignOut}>Sign out</button>}{notice&&<p className="feedback" role="status">{notice}</p>}<div className="settings-divider"/><h3>Cloud progress</h3><p>{supabase?'Cloud account connection is available. Only the signed-in learner can access their own profile, sessions, and scores.':'Local mode is active. Configure VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY in Netlify to enable account login.'}</p></div></>}
   <footer className="page-footer"><span>✦</span> Keep asking questions. Keep discovering. <span>✦</span><small>Knowledge Quest · Made for curious minds</small></footer>
   </div>
  </main>
  {chosenLesson&&<div className="modal-scrim" onClick={()=>setChosenLesson(null)}><section className="lesson-modal" role="dialog" aria-modal="true" aria-labelledby="lesson-title" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setChosenLesson(null)} aria-label="Close lesson">×</button><span className="lesson-emoji">{chosenLesson.emoji}</span><div className="section-kicker">{chosenLesson.subject.toUpperCase()} · {chosenLesson.duration} · 3 STEPS</div><h2 id="lesson-title">{chosenLesson.title}</h2><div className="lesson-step"><span>01 · LEARN</span><p>{chosenLesson.text}</p></div><div className="lesson-step example"><span>02 · SEE IT</span><p>{chosenLesson.example}</p></div><div className="lesson-step pitfall"><span>WATCH OUT</span><p>{chosenLesson.pitfall}</p></div><form className="lesson-check" onSubmit={e=>{e.preventDefault();const response=lessonAnswer.trim().toLowerCase();const correct=response.length>0&&response.includes(chosenLesson.answer);const masteredNow=correct||lessonMastered;setLessonMastered(masteredNow);setLessonFeedback(correct?'That’s it! You connected the idea to a new example. ✨':masteredNow?'You’ve already mastered this lesson. Try explaining the idea in your own words!':'Not quite yet. Reread the example and try again.')}}><label htmlFor="lesson-answer">03 · CHECK YOUR UNDERSTANDING</label><p>{chosenLesson.question}</p><div className="lesson-answer-row"><input id="lesson-answer" value={lessonAnswer} onChange={e=>setLessonAnswer(e.target.value)} placeholder="Your answer" autoComplete="off"/><button className="btn-secondary" type="submit">Check</button></div></form>{lessonFeedback&&<p className={'lesson-feedback '+(lessonMastered?'correct':'') } role="status">{lessonFeedback}</p>}{showLessonHint&&<p className="lesson-hint">Hint: {chosenLesson.example}</p>}<button className="text-link lesson-hint-button" onClick={()=>setShowLessonHint(true)}>Need a hint?</button><div className="lesson-reflect"><strong>Think about it</strong><p>{chosenLesson.reflect}</p></div><button className="btn-primary" disabled={!lessonMastered} onClick={()=>{complete(chosenLesson.title,10);setChosenLesson(null)}}>{completed.includes(chosenLesson.title)?'Lesson complete': 'Finish lesson +10 stars'} <Check size={16}/></button></section></div>}
 </div>;
}
type FinishGame = (score:number)=>void;
function GameExperience({game,onFinish}:{game:Game;onFinish:FinishGame}){
 if(game.id==='turbo-car-racer') return <MeteorDash game={game} onFinish={onFinish}/>;
 if(game.id==='veggie-slice') return <RainbowGarden game={game} onFinish={onFinish}/>;
 if(game.id==='mine-blast') return <CrystalMemory game={game} onFinish={onFinish}/>;
 if(game.id==='river-boat-adventure') return <RiverRescue game={game} onFinish={onFinish}/>;
 return <PlanetPathfinder game={game} onFinish={onFinish}/>;
}
function GameFrame({game,score,progress,children}:{game:Game;score:number;progress:number;children:ReactNode}){
 return <section className={'game-frame '+game.color}><div className="game-frame-head"><div><span className="game-kicker">{game.category} · FIELD MISSION</span><h1>{game.title}</h1><p>{game.description}</p></div><div className="game-score-badge"><span>✦</span><strong>{score}</strong><small>stardust</small></div></div><div className="game-progress-head"><span>MISSION PROGRESS</span><strong>{progress}%</strong></div><div className="game-progress"><i style={{width:progress+'%'}}/></div>{children}</section>;
}
function MissionReward({score,onFinish,children}:{score:number;onFinish:FinishGame;children:ReactNode}){
 const [claimed,setClaimed]=useState(false);
 return <div className="mission-reward"><span className="reward-sparkle">✨</span><div><strong>Mission complete!</strong><p>{children}</p></div>{claimed?<span className="completed-label"><Check size={15}/> Stars collected</span>:<button className="btn-primary" onClick={()=>{setClaimed(true);onFinish(score)}}>Collect {score} ⭐</button>}</div>;
}
const raceStages=[
 {scene:'Stardust straightaway',tip:'The bright middle lane is clear!',lanes:['🪨','🌟','🟢']},
 {scene:'Comet crossing',tip:'Comets sweep across the outside lanes.',lanes:['☄️','🟢','☄️']},
 {scene:'Moonrock tunnel',tip:'Look for the gap between the rocks.',lanes:['🪨','🟢','🌟']},
 {scene:'Twinkle bridge',tip:'A star trail is waiting on the right.',lanes:['🟢','🪨','🌟']},
 {scene:'Nebula bend',tip:'The middle glows with safe stardust.',lanes:['🪨','🌟','🪨']},
 {scene:'Finish-line comet',tip:'The left lane has a clear run home.',lanes:['🟢','☄️','🪨']},
];
function MeteorDash({game,onFinish}:{game:Game;onFinish:FinishGame}){
 const [step,setStep]=useState(0);const [score,setScore]=useState(0);const [shields,setShields]=useState(3);const [feedback,setFeedback]=useState('');const [carLane,setCarLane]=useState(1);
 const done=step>=raceStages.length;const stage=raceStages[Math.min(step,raceStages.length-1)];
 const choose=(lane:number)=>{setCarLane(lane);const event=stage.lanes[lane];if(event==='🌟'){setScore(s=>s+15);setFeedback('Stardust collected! A bright choice. +15');}else if(event==='🪨'||event==='☄️'){setShields(h=>Math.max(0,h-1));setFeedback('Bump! Your shield absorbed it. Watch the route hint next time.');}else{setScore(s=>s+5);setFeedback('Smooth driving! +5 for a safe lane.');}setStep(s=>s+1);};
 return <GameFrame game={game} score={score} progress={Math.round(step/raceStages.length*100)}><div className="race-scene"><div className="scene-copy"><span>ROUTE {Math.min(step+1,raceStages.length)} / {raceStages.length}</span><h2>{done?'Finish line!':stage.scene}</h2><p>{done?'You piloted your racer across the whole star road.':stage.tip}</p><div className="shield-line">🛡️ Shields <strong>{'💚'.repeat(shields)||'✨'}</strong></div></div><div className="race-road" aria-label="Three-lane cosmic road">{[0,1,2].map((lane)=><button key={lane} className={'race-lane '+(lane===carLane?'race-lane-car':'')} disabled={done} onClick={()=>choose(lane)}><span className="lane-label">{['LEFT','MIDDLE','RIGHT'][lane]}</span><strong>{done?'🏁':stage.lanes[lane]}</strong><small>{lane===carLane?'🏎️ Your racer':'Choose lane'}</small></button>)}</div></div>{feedback&&<div className="game-feedback" role="status">{feedback}</div>}{done&&<MissionReward score={score} onFinish={onFinish}>You chose a lane at every checkpoint and made it to the finish. Best racers look ahead and adjust.</MissionReward>}<div className="game-coach"><Sparkles size={16}/><span>Tip: use the route clue to make a prediction before you steer.</span></div></GameFrame>;
}
const gardenRounds=[
 {prompt:'Find a red fruit for the picnic basket.',options:[['🍎','Apple'],['🥦','Broccoli'],['🥕','Carrot'],['🍇','Grapes']],answer:'Apple',fact:'Apples grow on trees. Their flowers need pollinators to help fruit form.'},
 {prompt:'Choose a leafy green for the garden salad.',options:[['🥬','Lettuce'],['🍓','Strawberry'],['🌽','Corn'],['🥔','Potato']],answer:'Lettuce',fact:'Leaves help plants catch sunlight and make sugars through photosynthesis.'},
 {prompt:'Which garden food grows beneath the soil?',options:[['🥕','Carrot'],['🍅','Tomato'],['🍐','Pear'],['🥒','Cucumber']],answer:'Carrot',fact:'A carrot is a root. Roots anchor plants and take up water and minerals.'},
 {prompt:'The seedlings are thirsty. What should we bring?',options:[['💧','Water'],['🧊','Ice cubes'],['🧃','Juice'],['🪨','Pebbles']],answer:'Water',fact:'Plants use water to move nutrients and keep their stems and leaves firm.'},
 {prompt:'A bee is visiting the blossoms. What garden job can it help with?',options:[['🌼','Pollination'],['🌧️','Making rain'],['🌙','Making moonlight'],['🪨','Making soil rocks']],answer:'Pollination',fact:'When pollen moves between flowers, many plants can make seeds and fruit.'},
 {prompt:'Choose a crunchy orange root for our rainbow plate.',options:[['🥕','Carrot'],['🍉','Watermelon'],['🫛','Peas'],['🍄','Mushroom']],answer:'Carrot',fact:'A rainbow plate uses different colorful plant foods for variety.'},
];
function RainbowGarden({game,onFinish}:{game:Game;onFinish:FinishGame}){
 const [step,setStep]=useState(0);const [score,setScore]=useState(0);const [streak,setStreak]=useState(0);const [feedback,setFeedback]=useState('');const [correct,setCorrect]=useState(false);
 const done=step>=gardenRounds.length;const round=gardenRounds[Math.min(step,gardenRounds.length-1)];
 const choose=(label:string)=>{if(correct)return;if(label===round.answer){setCorrect(true);setScore(s=>s+10+Math.min(streak*2,6));setStreak(s=>s+1);setFeedback('Garden genius! '+round.fact);}else{setStreak(0);setFeedback('Not quite. Try another garden friend — there is no penalty for exploring!');}};
 const next=()=>{setStep(s=>s+1);setCorrect(false);setFeedback('');};
 return <GameFrame game={game} score={score} progress={Math.round(step/gardenRounds.length*100)}><div className="garden-world"><div className="garden-sky"><span>🌤️</span><span>🦋</span><span>🐝</span><span>🌈</span></div><div className="garden-task"><span>GARDEN JOB {Math.min(step+1,gardenRounds.length)} / {gardenRounds.length}</span><h2>{done?'The garden is blooming!':round.prompt}</h2><p>Pick a card to help your garden grow. Build a streak for bonus stars!</p></div><div className="garden-options">{done?null:round.options.map(([emoji,label])=><button key={label} disabled={correct} className={'garden-option '+(correct&&label===round.answer?'garden-correct':'')} onClick={()=>choose(label)}><span>{emoji}</span><strong>{label}</strong></button>)}</div><div className="garden-streak">🔥 Growing streak <strong>{streak}</strong> <span>· Basket {Math.min(step,gardenRounds.length)}/{gardenRounds.length}</span></div></div>{feedback&&<div className={'game-feedback '+(correct?'game-feedback-good':'')} role="status">{feedback}</div>}{correct&&!done&&<button className="btn-primary game-next" onClick={next}>Next garden job <ChevronRight size={16}/></button>}{done&&<MissionReward score={score} onFinish={onFinish}>You finished every garden job. Tiny changes — water, roots, leaves, and pollinators — help a garden thrive.</MissionReward>}</GameFrame>;
}
const crystals=['💎','🔮','🟣','🔷','🟢','💠'];
function CrystalMemory({game,onFinish}:{game:Game;onFinish:FinishGame}){
 const [deck]=useState(()=>[...crystals,...crystals].map((face,id)=>({id,face})).sort(()=>Math.random()-.5));const [flipped,setFlipped]=useState<number[]>([]);const [matched,setMatched]=useState<number[]>([]);const [score,setScore]=useState(0);const [moves,setMoves]=useState(0);const [feedback,setFeedback]=useState('Flip any two crystals to begin.');
 const waiting=flipped.length===2&&deck[flipped[0]]?.face!==deck[flipped[1]]?.face;const done=matched.length===deck.length;
 const turn=(id:number)=>{if(done||waiting||matched.includes(id)||flipped.includes(id))return;if(flipped.length===0){setFlipped([id]);setFeedback('Find the crystal twin that matches this one.');return;}const first=flipped[0];setMoves(m=>m+1);if(deck[first].face===deck[id].face){setFlipped([first,id]);setMatched(m=>[...m,first,id]);setScore(s=>s+Math.max(8,18-Math.floor(moves/3)));setFeedback('A match! Your memory map is growing. +18 stars');}else{setFlipped([first,id]);setFeedback('Different crystals. Take a moment to remember both, then flip them back.');}};
 const flipBack=()=>{setFlipped([]);setFeedback('Choose two crystals. Can you find a pair?');};
 return <GameFrame game={game} score={score} progress={Math.round(matched.length/deck.length*100)}><div className="memory-layout"><div className="memory-intro"><div className="memory-orb">🔮</div><div><span>CRYSTAL CAVE</span><h2>Find all 6 crystal pairs</h2><p>Turn over two crystals. Remember their symbols and locations.</p></div></div><div className="memory-stats"><span>✨ Pairs <strong>{matched.length/2}/6</strong></span><span>🧠 Turns <strong>{moves}</strong></span></div><div className="memory-grid">{deck.map((card,id)=><button key={id} aria-label={matched.includes(id)?`Matched ${card.face}`:flipped.includes(id)?card.face:'Face-down crystal'} className={'memory-card '+((flipped.includes(id)||matched.includes(id))?'memory-face-up':'')+(matched.includes(id)?' memory-matched':'')} onClick={()=>turn(id)} disabled={matched.includes(id)||waiting}><span>{flipped.includes(id)||matched.includes(id)?card.face:'✦'}</span></button>)}</div>{waiting&&<button className="btn-secondary flip-back" onClick={flipBack}>I’ve memorized them — flip back</button>}</div><div className="game-feedback" role="status">{feedback}</div>{done&&<MissionReward score={score} onFinish={onFinish}>Every pair found in {moves} turns. Remembering locations helped you reveal the whole cave.</MissionReward>}</GameFrame>;
}
const riverStops=[
 {title:'The fork in the river',story:'The rescue map shows two routes to the village.',choices:[{label:'Take the wide, calm bend',icon:'🧭',supplies:1,hull:0,lesson:'A longer route can be safer when the current is strong.'},{label:'Ride the quick current',icon:'🌊',supplies:2,hull:-1,lesson:'Fast water saves time but can bump the boat on rocks.'}]},
 {title:'Rain over the canyon',story:'Dark clouds are gathering above the narrow gorge.',choices:[{label:'Tie up under a sheltered bank',icon:'🌳',supplies:0,hull:0,lesson:'Shelter helps protect a boat from wind and heavy rain.'},{label:'Paddle through before it pours',icon:'🏞️',supplies:1,hull:-1,lesson:'Weather forecasts help crews decide when to travel.'}]},
 {title:'A floating log',story:'A fallen branch is drifting toward the boat.',choices:[{label:'Slow down and steer around it',icon:'🪵',supplies:0,hull:0,lesson:'Slowing down gives you more time to react to an obstacle.'},{label:'Use the side channel',icon:'↗️',supplies:1,hull:-1,lesson:'A narrow channel may be quicker, but needs careful steering.'}]},
 {title:'A family waves for help',story:'A riverside family needs a lift to the next landing.',choices:[{label:'Bring them aboard carefully',icon:'🛟',supplies:-1,hull:0,lesson:'Rescue crews check that everyone has a safe seat and life jacket.'},{label:'Call the landing team by radio',icon:'📻',supplies:0,hull:0,lesson:'Clear radio messages help nearby teams respond quickly.'}]},
 {title:'Wind fills the sails',story:'The river widens and a friendly breeze picks up.',choices:[{label:'Raise the sail and guide the boat',icon:'⛵',supplies:1,hull:0,lesson:'A sail turns wind energy into forward motion.'},{label:'Row together as a crew',icon:'🚣',supplies:0,hull:0,lesson:'Working in rhythm makes rowing more efficient.'}]},
 {title:'The village landing',story:'You can see the clinic dock and its waiting helpers.',choices:[{label:'Deliver the medical supply box',icon:'📦',supplies:-1,hull:0,lesson:'Planning a route and sharing supplies can help a whole community.'},{label:'Ask the dock team to unload together',icon:'🤝',supplies:-1,hull:0,lesson:'Teams work best when everyone has a clear, helpful role.'}]},
];
function RiverRescue({game,onFinish}:{game:Game;onFinish:FinishGame}){
 const [step,setStep]=useState(0);const [score,setScore]=useState(0);const [supplies,setSupplies]=useState(2);const [hull,setHull]=useState(3);const [feedback,setFeedback]=useState('');const [choiceMade,setChoiceMade]=useState(false);
 const done=step>=riverStops.length;const stop=riverStops[Math.min(step,riverStops.length-1)];
 const choose=(choice:typeof riverStops[number]['choices'][number])=>{if(choiceMade)return;setChoiceMade(true);setHull(h=>Math.max(1,Math.min(3,h+choice.hull)));setSupplies(s=>Math.max(0,s+choice.supplies));const points=choice.hull<0?7:choice.supplies>0?13:10;setScore(s=>s+points);setFeedback(choice.lesson+' +'+points+' stars');};
 const next=()=>{setStep(s=>s+1);setChoiceMade(false);setFeedback('');};
 return <GameFrame game={game} score={score} progress={Math.round(step/riverStops.length*100)}><div className="river-world"><div className="river-bank"><span>🏞️</span><span>🌲</span><span>💦</span><span>🐦</span></div><div className="river-dashboard"><span>🛶 Hull <strong>{'💙'.repeat(hull)}</strong></span><span>📦 Supplies <strong>{supplies}</strong></span></div><div className="river-event"><span>RIVER JOURNAL · STOP {Math.min(step+1,riverStops.length)} / {riverStops.length}</span><h2>{done?'A wonderful welcome at the dock!':stop.title}</h2><p>{done?'The rescue team has everything they need. Your choices shaped the journey.':stop.story}</p></div>{!done&&<div className="river-choices">{stop.choices.map(choice=><button key={choice.label} className="river-choice" disabled={choiceMade} onClick={()=>choose(choice)}><span>{choice.icon}</span><strong>{choice.label}</strong><small>Choose this route</small></button>)}</div>}{choiceMade&&<button className="btn-primary game-next" onClick={next}>Continue downriver <ChevronRight size={16}/></button>}{done&&<MissionReward score={score} onFinish={onFinish}>You reached the village with {supplies} supply boxes aboard. Thoughtful choices kept the boat moving and the crew safe.</MissionReward>}</div>{feedback&&<div className="game-feedback game-feedback-good" role="status">{feedback}</div>}</GameFrame>;
}
const spaceStops:{world:string;emoji:string;goal:string;tools:[string,string,boolean][];fact:string}[]=[
 {world:'Mars',emoji:'🔴',goal:'Look beneath the dusty surface for signs of ancient water.',tools:[['📷','High-resolution camera',false],['🛰️','Ground-penetrating radar',true],['🔭','Radio telescope',false]],fact:'Radar can send signals into the ground and measure reflections. Scientists use it to map buried ice on Mars.'},
 {world:'Saturn',emoji:'🪐',goal:'Find out what chemicals make up the planet’s upper clouds.',tools:[['🌈','Infrared spectrometer',true],['🛞','Sample-collecting rover',false],['📡','Seismometer',false]],fact:'A spectrometer separates light into colors. Different chemicals leave different patterns in that light.'},
 {world:'The Moon',emoji:'🌕',goal:'Listen for tiny shakes to learn what is inside the Moon.',tools:[['📷','Panorama camera',false],['🌡️','Thermometer',false],['📈','Seismometer',true]],fact:'Seismometers record vibrations. Moonquakes help researchers learn about the Moon’s layers.'},
 {world:'Jupiter',emoji:'🟠',goal:'Map the invisible magnetic bubble around this giant planet.',tools:[['🧲','Magnetometer',true],['🧪','Soil scoop',false],['🌧️','Rain gauge',false]],fact:'A magnetometer measures magnetic fields. Jupiter has the strongest planetary magnetic field in our Solar System.'},
];
function PlanetPathfinder({game,onFinish}:{game:Game;onFinish:FinishGame}){
 const [step,setStep]=useState(0);const [score,setScore]=useState(0);const [feedback,setFeedback]=useState('');const [logged,setLogged]=useState(false);
 const done=step>=spaceStops.length;const stop=spaceStops[Math.min(step,spaceStops.length-1)];
 const choose=(tool:string,right:boolean)=>{if(logged)return;if(right){setLogged(true);setScore(s=>s+20);setFeedback('Perfect instrument choice! '+stop.fact);}else setFeedback('That tool measures something else. Think about the mission goal and try again.');};
 const next=()=>{setStep(s=>s+1);setLogged(false);setFeedback('');};
 return <GameFrame game={game} score={score} progress={Math.round(step/spaceStops.length*100)}><div className="space-world"><div className="space-orbit"><span className="space-world-emoji">{done?'🌌':stop.emoji}</span><span className="space-moon">✦</span><span className="space-moon second">✧</span></div><div className="space-brief"><span>MISSION {Math.min(step+1,spaceStops.length)} / {spaceStops.length} · SCIENCE LAB</span><h2>{done?'Discovery data secured!':`Explore ${stop.world}`}</h2><p>{done?'Your mission log is full of new discoveries.':stop.goal}</p></div>{!done&&<><div className="instrument-heading">Choose a science instrument</div><div className="instrument-grid">{stop.tools.map(([icon,label,right])=><button key={label} disabled={logged} className={'instrument-card '+(logged&&right?'instrument-correct':'')} onClick={()=>choose(label,Boolean(right))}><span>{icon}</span><strong>{label}</strong></button>)}</div></>}{logged&&!done&&<button className="btn-primary game-next" onClick={next}>Log discovery <ChevronRight size={16}/></button>}{done&&<MissionReward score={score} onFinish={onFinish}>You chose an instrument at every stop and logged four discoveries. Scientists match the tool to the question they want to investigate.</MissionReward>}</div>{feedback&&<div className={'game-feedback '+(logged?'game-feedback-good':'')} role="status">{feedback}</div>}</GameFrame>;
}
function Stat({icon,label,value,note,color}:{icon:ReactNode;label:string;value:string;note:string;color:string}){return <div className="stat-card"><span className={'stat-icon '+color}>{icon}</span><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-note">{note}</div></div>}
function PageIntro({kicker,title,text}:{kicker:string;title:string;text:string}){return <section className="page-intro"><div className="section-kicker">{kicker}</div><h1>{title}</h1><p>{text}</p></section>}
function SubjectCard({subject:s,onClick}:{subject:typeof subjects[number];onClick:()=>void}){return <button className="subject-card" onClick={onClick}><div className="subject-card-top"><span className={'subject-icon '+s.color}><s.icon size={20}/></span><span className="card-arrow"><ChevronRight size={16}/></span></div><strong>{s.name}</strong><p>{s.sub}</p><div className="subject-progress"><span><i style={{width:'32%'}}/></span><small>Explore topic</small></div></button>}
function GameCard({game:g,onClick}:{game:Game;onClick:()=>void}){return <button className={'game-card '+g.color} onClick={onClick}><div className="game-art"><div className="game-art-orbit"/><span>{g.emoji}</span><i>✦</i><b>✧</b></div><div className="game-card-body"><div className="game-meta"><span>{g.category}</span><span className="play-label"><Gamepad2 size={13}/> PLAY</span></div><strong>{g.title}</strong><p>{g.description}</p><div className="game-card-bottom"><span>Collect stars <span className="mini-star">✦</span></span><span className="round-arrow"><ChevronRight size={16}/></span></div></div></button>}

